// 模块 id / 配置 text -> 图标中文名（覆盖 tabbar 候选与快捷入口）
const ID_TO_NAME = {
  home: '首页',
  profile: '我的',
  diary: '日记',
  accounting: '记账',
  health: '健康',
  checkin: '打卡',
  todo: '待办',
  stats: '统计',
  calendar: '日历',
  timeline: '时间线',
  anniversary: '纪念日',
  wishlist: '愿望清单',
  reading: '阅读',
  movie: '观影',
};

// 兜底：按中文名直取，按 id 映射，未知返回空
function moduleNameOf(value) {
  if (!value) return '';
  if (ID_TO_NAME[value]) return ID_TO_NAME[value];
  return value;
}

module.exports = { MODULE: MODULE, ID_TO_NAME: ID_TO_NAME, moduleNameOf: moduleNameOf };
